<div key={job.id} className="job-card">
  <img src={job.logoUrl || 'https://via.placeholder.com/50'} alt="logo" className="job-logo" />

  <div className="job-main">
    <div className="job-details">
      <h3 className="job-title">{job.title}</h3>
      <p className="job-company">{job.company}</p>
      <p className="job-location">{job.location}</p>
    </div>

    <div className="job-tags">
      {job.tags?.split(',').map((tag, idx) => (
        <span key={idx} className="job-tag">{tag.trim()}</span>
      ))}
    </div>

    <div className="job-meta">
      <p className="job-date">📅 {job.postedOn || 'Today'}</p>
    </div>
  </div>

  <div className="job-actions">
    <a href={job.link} target="_blank" rel="noopener noreferrer">View Job</a>
    <button onClick={() => axios.delete(`http://localhost:5000/jobs/${job.id}`).then(fetchJobs)}>Delete</button>
  </div>
</div>
